query:
-- Verificar o equipamento no cadastro
SELECT id, codigoTag, nomeDoEquipamento, excluidoCusto FROM equipamentos 
WHERE codigoTag LIKE '%PERFURATRIZ%' OR nomeDoEquipamento LIKE '%PERFURATRIZ HIDR%';

-- Verificar nos itens importados
SELECT DISTINCT equipamentoTag, equipamentoDescricao, equipamentoSistemaId 
FROM item_despesa_importado 
WHERE equipamentoTag LIKE '%PERFURATRIZ HIDR%01%';

-- Verificar a tag excluída
SELECT * FROM equipamento_excluido_tag WHERE tag LIKE '%PERFURATRIZ%';

